let p = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;

if (!p || typeof p !== 'object') return null;

if (!p.tracker_id || typeof p.tracker_id !== 'string') return null;
if (!p.ts || isNaN(Date.parse(p.ts))) return null;
if (typeof p.lat !== 'number' || p.lat < -90 || p.lat > 90) return null;
if (typeof p.lon !== 'number' || p.lon < -180 || p.lon > 180) return null;
if (typeof p.speed !== 'number' || p.speed < 0) return null;
if (typeof p.activity !== 'number' || p.activity < 0 || p.activity > 1) return null;
if (typeof p.battery !== 'number' || p.battery < 0 || p.battery > 100) return null;

msg.payload = p;
msg.headers = {
    'Content-Type': 'application/json',
    'X-API-Key': env.get('INGEST_API_KEY') || 'dev-ingest-key-123'
};
return msg;
